WHERE 1 = 1

   AND T1.SERVICE_CODE LIKE '%' || #{serviceCode} || '%'


   AND T1.SERVICE_NAME LIKE '%' || #{serviceName} || '%'


   AND T1.BUSINESS_CODE = #{businessCode}


   AND T1.SCID LIKE '%' || #{scid} || '%'


   AND T1.ENABLED = #{enabled}


   AND T1.STATUS = #{status}


   AND T1.ONLINE_FORCE_YN = #{onlineForceYn}

