SELECT * FROM (
  SELECT a.*, ROWNUM rnum
    FROM (
       SELECT /* mkcoa6666S0_S0 */

         FROM TB_OM_SVC_CATALOG T1

        ORDER BY T1.CHG_DTM DESC, T1.SERVICE_CODE ASC
    ) a
   WHERE ROWNUM <= #{offset} + #{pageSize}
)
WHERE rnum > #{offset}

SELECT /* mkcoa6666S1_S0 */

  FROM TB_OM_SVC_CATALOG T1
 WHERE T1.SERVICE_CODE = #{serviceCode}

