UPDATE /* mkcoa6666U0_U0 */ TB_OM_SVC_CATALOG
   SET SERVICE_NAME           = #{serviceName}
     , BUSINESS_CODE          = #{businessCode}
     , SCID                   = #{scid}
     , ENABLED                = #{enabled}
     , STATUS                 = #{status}
     , ALLOWED_SYSTEM_IDS     = #{allowedSystemIds}
     , ALLOWED_TERMINAL_TYPES = #{allowedTerminalTypes}
     , ALLOWED_BRANCHES       = #{allowedBranches}
     , REQUIRED_AUTHORITIES   = #{requiredAuthorities}
     , SYNC_TYPE              = #{syncType}
     , ALLOWED_START_TIME     = #{allowedStartTime}
     , ALLOWED_END_TIME       = #{allowedEndTime}
     , TIMEOUT_MS             = #{timeoutMs}
     , MAX_TPS                = #{maxTps}
     , MAX_CONCURRENT         = #{maxConcurrent}
     , DUPLICATE_WINDOW_SEC   = #{duplicateWindowSec}
     , AUDIT_LEVEL            = #{auditLevel}
     , REASON                 = #{reason}
     , ONLINE_FORCE_YN        = #{onlineForceYn}
     , POLICY_JSON            = #{policyJson}
     , CHG_DTM                = #{chgDtm}
 WHERE SERVICE_CODE = #{serviceCode}

UPDATE /* mkcoa6666U1_U0 */ TB_OM_SVC_CATALOG
   SET STATUS          = #{status}
     , ENABLED         = #{enabled}
     , ONLINE_FORCE_YN = #{onlineForceYn}
     , REASON          = #{reason}
     , CHG_DTM         = #{chgDtm}
 WHERE SERVICE_CODE = #{serviceCode}

mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM rnum FROM ( SELECT /* mkcoa6666S3_S0 */ T1.RESULT_ID AS RESULT_ID , T1.STD_GBL_ID AS STD_GBL_ID , T1.SERVICE_CODE AS SERVICE_CODE , T1.OPTR_ENO AS OPTR_ENO , T1.TR_BRC AS TR_BRC , T1.TRM_KDC AS TRM_KDC , T1.TR_TRM_IPADR AS TR_TRM_IPADR , T1.CONTROL_RESULT AS CONTROL_RESULT , T1.ERROR_CODE AS ERROR_CODE , T1.REASON AS REASON , T1.CHECK_STEP AS CHECK_STEP , T1.REG_DTM AS REG_DTM FROM TB_OM_TX_CTRL_RESULT T1 WHERE 1 = 1
AND T1.SERVICE_CODE = #{serviceCode}
ORDER BY T1.REG_DTM DESC, T1.RESULT_ID DESC ) a WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rnum > #{offset}

SELECT COUNT(*)
  FROM TB_OM_TX_CTRL_RESULT T1
 WHERE T1.SERVICE_CODE = #{serviceCode}
   AND T1.CONTROL_RESULT <> 'ALLOW'
   AND T1.REG_DTM >= #{fromDtm}

