) VALUES (
    #{resultId}, #{stdGblId}, #{serviceCode}, #{optrEno}, #{trBrc}, #{trmKdc}, #{trTrmIpadr},
    #{controlResult}, #{errorCode}, #{reason}, #{checkStep}, #{regDtm}
